import json, math

def by_variant(samples):
    d={}
    for s in samples: d.setdefault(s['variant'],[]).append(s)
    return d

def coverage_vote(samples):
    d = by_variant(samples)
    cov = {}
    for v, lst in d.items():
        answers_in_variant = set(s['answer'] for s in lst)
        for a in answers_in_variant:
            cov[a] = cov.get(a,0)+1
    # tie-break by total count
    counts={}
    for s in samples: counts[s['answer']]=counts.get(s['answer'],0)+1
    best = max(cov.items(), key=lambda kv: (kv[1], counts[kv[0]]))
    return best[0]

def majority_vote(samples):
    counts={}
    for s in samples: counts[s['answer']]=counts.get(s['answer'],0)+1
    return max(counts.items(), key=lambda x:x[1])[0]

for f in ['alg_deep.json','geo_deep.json','comb_deep.json','nt_deep.json']:
    qs = json.load(open(f))['questions']
    n=len(qs)
    cov_acc=0; mv_acc=0
    for q in qs:
        if coverage_vote(q['samples'])==q['correct_answer']: cov_acc+=1
        if majority_vote(q['samples'])==q['correct_answer']: mv_acc+=1
    print(f, 'coverage(30 samples)', cov_acc/n, 'majority(30)', mv_acc/n)
